projectFiles.extension-project/.pi/extensions/dynamic:
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';

export default function (pi) {
  pi.on('resources_discover', ({ cwd, reason }) => {
    const phase = reason === 'reload' ? 'reloaded' : 'startup';
    const root = join(cwd, '.pi', 'extension-resources', phase);
    return {
      skillPaths: [pathToFileURL(join(root, 'skills')).href],
      promptPaths: [join(root, 'prompts')],
      themePaths: [join(root, 'themes')],
    };
  });
}
